 return `${d.schedule.some(s=>s.type==='scene'&&Records.deleted(project,'scenes',s.sceneId))?'<p class="inline-notice">Deleted scene schedule links are retained for Restore in Production Data → Scenes. Their times and personal calls remain stored; deleted scenes are omitted from draft output.</p>':''}${!locked()?`<div class="toolbar"><select id="add-scene-select" aria-label="Scene to add">${options(activeScenes().map(s=>({id:s.id,name:s.number+' · '+s.slug})),'')}</select><button data-action="add-scene">Add scene & cast</button><button data-action="add-break">+ Break / move</button></div>`:''}${d.schedule.some(s=>s.type!=='scene'||!Records.deleted(project,'scenes',s.sceneId))?d.schedule.map((s,i)=>{if(s.type==='scene'&&Records.deleted(project,'scenes',s.sceneId))return '';const sc=project.scenes.find(a=>a.id===s.sceneId),p=prefix+'.'+i;return `<article class="row-card"><div class="row-title"><strong>${esc(sc?sc.number+' · '+sc.slug:s.type.toUpperCase())}</strong>${!locked()?`<button data-move="schedule:${i}:-1" ${Records.scheduleNeighbor(project,d.schedule,i,-1)<0?'disabled':''} aria-label="Move schedule item up">↑</button><button data-move="schedule:${i}:1" ${Records.scheduleNeighbor(project,d.schedule,i,1)<0?'disabled':''} aria-label="Move schedule item down">↓</button><button data-remove="schedule:${i}" aria-label="Remove schedule item">×</button>`:''}</div><div class="form-grid">${sc?field('Scene notes',p+'.notes','textarea',{wide:true,value:ScheduleNotes.resolve(s,sc),rows:4,note:Object.hasOwn(s,'notes')?'This schedule row only. <button type="button" data-scene-notes-reset="'+esc(s.id)+'">Use production scene notes</button>':'Uses production scene notes. Editing affects this schedule row only.'}):field('Start',p+'.start','time')+field('Day offset',p+'.offset','number',{extra:'min="0" max="3" step="1"'})+field('Minutes',p+'.duration','number',{extra:'min="0" max="1440" step="1"'})+field('Type',p+'.type','select',{items:['meal','move','break','note'],empty:null})}${field('Description override',p+'.description','textarea',{wide:true,note:sc?esc(sc.synopsis):''})}</div>${sc?`<button class="text-button" data-script="${sc.id}">View scene & source details</button>`:''}</article>`;}).join(''):'<p class="empty">Build the day from your production scene register. Add breaks and company moves as needed.</p>'}`;
