function refreshCoordinateFields(loc){const index=project.locations.findIndex(x=>x.id===loc.id);for(const k of ['latitude','longitude']){const input=document.querySelector(`[data-bind="locations.${index}.${k}"]`);if(input)input.value=loc[k]??'';}document.querySelectorAll('[data-coordinate-info]').forEach(el=>{if(el.dataset.coordinateInfo===loc.id)el.innerHTML=coordinateInfo(loc);});}
function applyMapCoordinates(loc,result,expected,force=false){const applied=window.LocationMaps.applyCoordinates(loc,result,expected,{force}),key=project.id+':'+loc.id;coordinateLookupState.set(key,{message:applied.reason,result,applied:applied.applied});if(applied.applied){for(const d of project.days)d.weather.approved=false;mark();}refreshCoordinateFields(loc);return applied;}
async function lookupLocationCoordinates(id){if(!id||!project)return;const selected=project.id,loc=project.locations.find(l=>l.id===id);if(!loc||Records.deleted(project,'locations',id))return;const info=window.LocationMaps.inspect(loc.mapsUrl);if(!info.url)return;const key=selected+':'+id,token=(coordinateRequests.get(key)||0)+1;coordinateRequests.set(key,token);const expected=window.LocationMaps.capture(loc);coordinateLookupState.set(key,{message:'Resolving Maps coordinates…'});refreshCoordinateFields(loc);try{await flush();const result=await api.request('resolveLocationCoordinates',{projectId:selected,locationId:id,url:loc.mapsUrl});if(project.id!==selected||coordinateRequests.get(key)!==token)return;const current=project.locations.find(l=>l.id===id);if(!current||Records.deleted(project,'locations',id))return;applyMapCoordinates(current,result,expected);}catch(e){if(project.id===selected&&coordinateRequests.get(key)===token){coordinateLookupState.set(key,{message:e.message+' Coordinates were not changed; use Advanced for manual entry.'});const current=project.locations.find(l=>l.id===id);if(current)refreshCoordinateFields(current);}}}
function locationMapInfo(loc,kind){
 const spec=Details.places[kind],parking=kind!=='shoot',link=loc[spec.link]||'',address=loc[spec.address]||'',info=window.LocationMaps.inspect(link),key=esc(loc.id)+':'+kind;
 const message=info.status==='invalid'?'Use a full HTTPS Google Maps link. Other sites and invalid links cannot be opened.':info.status==='short'?'Short link: coordinates can resolve through Google. Open Maps to review/copy a missing address.':info.status==='no-address'?'No address text is embedded in this link. Open the map and enter the address manually.':info.status==='text'?'Text found in the link (review it; it may be a place name rather than a street address): '+info.text:'Paste a Google Maps link or enter a manual address. An address can also be opened as a Maps search.';
 return `<p class="tiny" role="status">${esc(message)}</p>${parking?'':'<div data-coordinate-info="'+esc(loc.id)+'">'+coordinateInfo(loc)+'</div>'}<div class="toolbar">${info.text&&info.text!==address?`<button data-map-use="${key}">${address?'Replace address with link text':'Use link text as address'}</button>`:''}<button data-map-open="${key}" ${info.status==='invalid'||!info.url&&!address.trim()?'disabled':''}>Open ${esc(spec.label.toLowerCase())} in Google Maps ↗</button></div>`;
}
// Coordinate status can change on blur/async completion. Keep address/map actions
// mounted so their pointer-down/up sequence cannot be interrupted by that lookup.
function coordinateInfo(loc){const info=window.LocationMaps.inspect(loc.mapsUrl),status=coordinateLookupState.get(project.id+':'+loc.id),source=loc.coordinateSource,sourceText=status?.message||(source&&source.kind!=='manual'?'Maps coordinates: '+loc.latitude+', '+loc.longitude+'. Confirm the venue.':loc.latitude!==null||loc.longitude!==null?'Manual coordinates retained in Advanced.':'No coordinates yet. Finish editing a Maps link to resolve them, or enter them in Advanced.');return `<p class="tiny coordinate-status" role="status">${esc(sourceText)}</p>${info.url?`<div class="toolbar"><button data-coordinate-lookup="${esc(loc.id)}">Resolve coordinates</button>${status?.result?.status==='resolved'&&!status?.applied?`<button data-coordinate-use="${esc(loc.id)}">Use Maps coordinates (${esc(status.result.coordinates.latitude)}, ${esc(status.result.coordinates.longitude)})</button>`:''}</div>`:''}`;}

function locationMapFields(loc,i,kind){const spec=Details.places[kind],p=`locations.${i}`;return `<fieldset class="location-place"><legend>${spec.label}</legend><div class="form-grid">${field('Google Maps link',p+'.'+spec.link,'text',{wide:true,extra:'inputmode="url" spellcheck="false"',note:'Optional. Manual addresses are never replaced automatically.'})}<div class="wide" data-map-info="${esc(loc.id)}:${kind}">${locationMapInfo(loc,kind)}</div>${field(spec.label+' address',p+'.'+spec.address,'textarea',{wide:true,rows:2,note:'Address / existing directions. Daily notes are separate in Locations & safety.'})}</div></fieldset>`;}
function refreshLocationMapInfo(path){const m=path.match(/^locations\.(\d+)\.(?:mapsUrl|parkingMapsUrl|basecampMapsUrl|hospitalMapsUrl|address|parking|basecampAddress|hospital)$/);if(!m)return;const loc=project.locations[Number(m[1])];if(!loc)return;document.querySelectorAll('[data-map-info]').forEach(el=>{for(const kind of Object.keys(Details.places))if(el.dataset.mapInfo===loc.id+':'+kind)el.innerHTML=locationMapInfo(loc,kind);});}
function masterLocations(){return `<div class="toolbar"><button class="primary" data-action="add-location">+ Add location</button><button data-location-collapse="all">Collapse all</button><button data-location-expand="all">Expand all</button>${recordTrashButton('locations')}</div><p class="tiny">Opening a map uses your browser and sends its link or search address to Google. Explicit place/pin coordinates are read from Maps links; supported short links resolve through Google after editing. Viewport camera positions are not used as venues. Manual coordinates always win unless you choose replacement. Address text still needs manual review; no paid API or new credentials are used.</p>${project.locations.map((l,i)=>{if(Records.deleted(project,'locations',l.id))return '';const p=`locations.${i}`;return `<details class="master-card location-card" data-location-card="${esc(l.id)}" ${readPreference('location-cards:'+project.id,{})[l.id]?'open':''}><summary><span>${esc(l.name||'New location')}</span></summary><div class="location-card-body"><p class="tiny">${l.verified?'Reviewed':'Needs review'}</p><div class="form-grid">${field('Location name',p+'.name')}</div>${locationMapFields(l,i,'shoot')}${locationMapFields(l,i,'parking')}${locationMapFields(l,i,'basecamp')}${locationMapFields(l,i,'hospital')}<div class="form-grid">${field('Emergency contact',p+'.emergencyPhone')}${field('Facility details verified by production',p+'.verified','checkbox')}</div><details class="location-advanced"><summary>Advanced · latitude and longitude</summary><p class="tiny">Coordinates are optional and never inferred from the map camera position. Shooting coordinates still drive solar/weather. Parking, basecamp and hospital coordinates are independent manual fields. Only shooting coordinates drive solar/weather.</p><div class="form-grid">${field('Shooting latitude',p+'.latitude','number',{extra:'min="-90" max="90"',note:'Blank is unknown, not 0°.'})}${field('Shooting longitude',p+'.longitude','number',{extra:'min="-180" max="180"'})}${field('Parking latitude',p+'.parkingLatitude','number',{extra:'min="-90" max="90"'})}${field('Parking longitude',p+'.parkingLongitude','number',{extra:'min="-180" max="180"'})}${['basecamp','hospital'].map(kind=>field(Details.places[kind].label+' latitude',p+'.'+kind+'Latitude','number',{extra:'min="-90" max="90"'})+field(Details.places[kind].label+' longitude',p+'.'+kind+'Longitude','number',{extra:'min="-180" max="180"'})).join('')}</div></details><div class="record-actions"><button class="danger" data-record-delete="locations:${esc(l.id)}" aria-label="Delete Location: ${esc(l.name||'Unnamed location')}">Delete Location</button></div></div></details>`;}).join('')}`;}

const clockDrafts=new Map();
const clockKey=path=>project.id+':'+path;
function commitClockInput(input,path,draft=clockDrafts.get(clockKey(path)),normalize=true){if(!draft)return true;try{const value=TimeDisplay.parse(draft.value,draft.mode);if(/^days\.\d+\.overrides\.meal$/.test(path)){const d=project.days[Number(path.split('.')[1])];if(d.lunchMode!=='manual'||d.overrides.meal!==value){Lunch.manual(d,value,Lunch.resolve(project,d).offset);mark();refreshLunchHint();}}else if(at(path)!==value){put(path,value);mark();}if(/(?:overrides|defaults)\.generalCall$/.test(path))refreshLunchFields();if(normalize){clockDrafts.delete(clockKey(path));if(input)input.value=TimeDisplay.format(value,draft.mode);}if(input){input.dataset.timeSaved=value;input.setAttribute('aria-invalid','false');document.getElementById('time-error-'+path).textContent='';}return true;}catch(e){if(input){input.setAttribute('aria-invalid','true');document.getElementById('time-error-'+path).textContent=e.message+' The saved time is unchanged. Correct it or press Escape to cancel.';}return false;}}
const temperatureDrafts=new Map();
function commitTemperature(input,path,text){const key=project.id+':'+path;try{const saved=input?.dataset.temperatureSaved??at(path)??'',display=Temperature.format(saved,tempMode()),entered=String(text).trim();const parsed=Temperature.parse(entered,tempMode());if(!(entered!==''&&display!==''&&Number(entered)===Number(display))&&entered!==display){put(path,parsed);if(input){input.dataset.temperatureSaved=parsed;const note=input.closest('label')?.querySelector('small:not(.page-length-error)');if(note)note.innerHTML=path.includes('.sheetOverrides.')?'Manual day override <button data-sheet-reset="'+path.split('.').at(-1)+'" type="button">Reset to inherited / forecast</button>':'Reusable manual production value';}mark();}if(input){input.value=Temperature.format(input.dataset.temperatureSaved,tempMode());input.removeAttribute('aria-invalid');const message=$('temperature-error-'+path);if(message)message.textContent='';}temperatureDrafts.delete(key);return true;}catch(e){if(input){input.setAttribute('aria-invalid','true');const message=$('temperature-error-'+path);if(message)message.textContent=e.message;}return false;}}
function bindTemperatures(){document.querySelectorAll('[data-temperature]').forEach(input=>{const path=input.dataset.temperature,key=project.id+':'+path;if(temperatureDrafts.has(key))input.value=temperatureDrafts.get(key);input.addEventListener('input',()=>{temperatureDrafts.set(key,input.value);input.removeAttribute('aria-invalid');});input.addEventListener('blur',()=>{if(temperatureDrafts.has(key))commitTemperature(input,path,input.value);});input.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();temperatureDrafts.delete(key);input.value=Temperature.format(input.dataset.temperatureSaved,tempMode());input.removeAttribute('aria-invalid');$('temperature-error-'+path).textContent='';}else if(e.key==='Enter'){e.preventDefault();commitTemperature(input,path,input.value);}});});}
function commitTemperatures(){let bad;for(const [key,text] of temperatureDrafts){if(!key.startsWith(project.id+':'))continue;const path=key.slice(project.id.length+1),input=document.querySelector(`[data-temperature="${path}"]`);if(!commitTemperature(input,path,text)&&!bad)bad=input;}if(bad){bad.focus();throw Error('A temperature needs correction; use a number in the displayed unit or Escape to keep its saved value.');}}
function commitClockTimes(){if(!project)return;let bad;for(const [key,draft] of clockDrafts){if(!key.startsWith(project.id+':'))continue;const path=key.slice(project.id.length+1),input=document.querySelector(`[data-clock-time="${path}"]`);if(!commitClockInput(input,path,draft)&&!bad)bad=input;}if(bad){const panel=bad.closest('details');if(panel)panel.open=true;bad.focus();throw Error('A time needs correction. Use the displayed format or press Escape to keep the saved time.');}}
function bindClockTimes(){document.querySelectorAll('[data-clock-time]').forEach(input=>{const path=input.dataset.clockTime;input.addEventListener('input',()=>{const draft={value:input.value,mode:timeMode()};clockDrafts.set(clockKey(path),draft);input.setAttribute('aria-invalid','false');document.getElementById('time-error-'+path).textContent='';try{TimeDisplay.parse(draft.value,draft.mode);commitClockInput(input,path,draft,false);}catch{}});input.addEventListener('blur',()=>commitClockInput(input,path));input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();commitClockInput(input,path);}if(event.key==='Escape'){event.preventDefault();event.stopPropagation();clockDrafts.delete(clockKey(path));input.value=showTime(input.dataset.timeSaved||'');input.setAttribute('aria-invalid','false');document.getElementById('time-error-'+path).textContent='';}});});}

const pageLengthDrafts=new Map();
const pageLengthKey=id=>project.id+':'+id;
function pageLengthField(scene){const draft=pageLengthDrafts.get(pageLengthKey(scene.id)),hint='length-help-'+scene.id,errorId='length-error-'+scene.id;return `<label class="field">Length (pages)<input type="text" maxlength="100" autocomplete="off" spellcheck="false" data-page-length="${esc(scene.id)}" aria-describedby="${esc(hint)} ${esc(errorId)}" aria-invalid="${draft?.error?'true':'false'}" value="${esc(draft?.value??PageLength.format(scene.eighths))}"><small id="${esc(hint)}">Pages, not eighth counts: 2 3/8, 3/8, 2 or 2.375. Exact eighths only. Commit with Tab/Enter; Escape cancels this edit.</small><small class="page-length-error" id="${esc(errorId)}" role="alert">${esc(draft?.error||'')}</small></label>`;}
function commitPageLength(scene,input,draft=pageLengthDrafts.get(pageLengthKey(scene.id))){
 if(!draft)return true;try{const eighths=PageLength.parse(draft.value);if(scene.eighths!==eighths){scene.eighths=eighths;mark();}pageLengthDrafts.delete(pageLengthKey(scene.id));if(input){input.value=PageLength.format(eighths);input.setAttribute('aria-invalid','false');document.getElementById('length-error-'+scene.id).textContent='';}return true;}
 catch(e){draft.error=e.message+' Current saved length '+PageLength.format(scene.eighths)+' pages is unchanged. Correct the text or press Escape to cancel.';if(input){input.setAttribute('aria-invalid','true');document.getElementById('length-error-'+scene.id).textContent=draft.error;}$('save-state').textContent='Page length not saved — correct or press Escape';return false;}
}
function commitPageLengths(){if(!project)return;commitTemperatures();commitClockTimes();let bad;for(const scene of activeScenes()){const input=document.querySelector(`[data-page-length="${scene.id}"]`);if(!commitPageLength(scene,input)&&!bad)bad=input;}if(bad){bad.closest('[data-scene-card]').open=true;bad.focus();throw Error('A scene page length needs correction. Its saved value has not changed; correct the text or press Escape to cancel.');}}
function bindPageLengths(){document.querySelectorAll('[data-page-length]').forEach(input=>{const scene=project.scenes.find(s=>s.id===input.dataset.pageLength);input.addEventListener('input',()=>{pageLengthDrafts.set(pageLengthKey(scene.id),{value:input.value,error:''});input.setAttribute('aria-invalid','false');document.getElementById('length-error-'+scene.id).textContent='';});input.addEventListener('blur',()=>commitPageLength(scene,input));input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();commitPageLength(scene,input);}if(event.key==='Escape'){event.preventDefault();event.stopPropagation();pageLengthDrafts.delete(pageLengthKey(scene.id));input.value=PageLength.format(scene.eighths);input.setAttribute('aria-invalid','false');document.getElementById('length-error-'+scene.id).textContent='';$('save-state').textContent=saved<dirty?'Saving…':'Saved on this device';}});});}
// Validate only on commit/navigation, never on each slash/space keystroke.
document.addEventListener('click',event=>{if(!event.target.closest('button,summary'))return;try{commitPageLengths();}catch(e){event.preventDefault();event.stopImmediatePropagation();error(e);}},true);
document.addEventListener('keydown',event=>{if(!['Enter',' '].includes(event.key)||!event.target.matches('summary'))return;try{commitPageLengths();}catch(e){event.preventDefault();event.stopImmediatePropagation();error(e);}},true);

function masterScenes(){return `<div class="toolbar"><button class="primary" data-action="add-scene-master">+ Add scene</button><button data-scene-collapse="all">Collapse all</button><button data-scene-expand="all">Expand all</button>${recordTrashButton('scenes')}</div><p class="tiny">Length is in pages, stored exactly at eighth-page precision. Draft schedules omit deleted scenes; retained personal calls are reviewed independently.</p>${project.scenes.map((s,i)=>{if(Records.deleted(project,'scenes',s.id))return '';const p=`scenes.${i}`,used=project.days.filter(d=>d.schedule.some(item=>item.sceneId===s.id));return `<details class="master-card location-card scene-card" data-scene-card="${esc(s.id)}" ${readPreference('scene-cards:'+project.id,{})[s.id]?'open':''}><summary><span>${esc(s.number)} · ${esc(s.slug||'Untitled scene')}</span></summary><div class="location-card-body"><div class="master-head"><span class="badge">${used.length?used.map(d=>esc(d.label)).join(', '):'Unscheduled'}</span><button data-script="${s.id}" class="text-button">Scene & shots</button></div><div class="form-grid">${field('Scene number',p+'.number')}${field('Title / slugline',p+'.slug')}${pageLengthField(s)}${field('Location',p+'.locationId','select',{items:activeLocations(),note:Records.deleted(project,'locations',s.locationId)?'This scene refers to a deleted location. Restore it or explicitly reassign.':''})}${field('Script day',p+'.scriptDay')}${field('Day / night code',p+'.dayNight')}${field('Department notes',p+'.notes','textarea',{wide:true})}${field('Synopsis',p+'.synopsis','textarea',{wide:true})}</div><p class="tiny">Cast: ${activePeople().filter(p=>p.type==='cast').map(who=>`<label class="check"><input type="checkbox" data-scene-cast="${i}:${who.id}" ${s.castIds.includes(who.id)?'checked':''}> ${esc(who.character||who.name)}</label>`).join('')}</p><div class="record-actions"><button class="danger" data-record-delete="scenes:${esc(s.id)}" aria-label="Delete Scene: ${esc(s.number+' · '+s.slug)}">Delete Scene</button></div></div></details>`;}).join('')}`;}

function renderProduction(){
 const tabs={general:'Production',cast:'Cast',crew:'Crew',locations:'Locations',scenes:'Scenes'},body=master==='general'?masterGeneral():master==='locations'?masterLocations():master==='scenes'?masterScenes():masterPeople(master);
 $('content').innerHTML=`<div class="master-layout"><section class="panel"><div class="master-tabs">${Object.entries(tabs).map(([k,v])=>`<button data-master="${k}" class="${k===master?'active':''}">${v}</button>`).join('')}</div><div class="panel-body master-list">${body}</div></section><aside class="panel help-panel"><div class="panel-body"><h3>Enter once. Reuse every day.</h3><p>Production records feed daily sheets by reference. Scene membership can help populate cast calls.</p><p>Contacts stay off PDFs unless explicitly included in the layout settings. Optional catering categories are counted for called people. Enter only information appropriate for the local project archive.</p><p>All edits save to a local SQLite database. Export a project archive for handoff or a portable backup.</p><p>${project.provenance?esc(project.provenance.source):'Your own production'}</p></div></aside></div>`;bindFields();
}
function renderRevisions(){
 $('content').innerHTML=shell('Issued revisions',revisions.length?revisions.map(r=>{const d=[...project.days,...(project.deletedDays||[])].find(d=>d.id===r.dayId);return `<article class="revision-card"><div><h3>${esc(d?.label||'Shooting day')} / R${r.number}</h3><p>${esc(r.issued)}</p><p>SHA-256 ${esc(r.hash.slice(0,20))}…</p></div><div><button data-revision-preview="${r.id}">View snapshot</button> <button data-revision-export="${r.id}">Export original PDF</button></div></article>`;}).join(''):'<p class="empty">No issued sheets yet. Finish a draft, review it, then issue a numbered revision.</p>');
}
function render(){previewSerial++;renderSide();renderHeader();if(view==='production')renderProduction();else if(view==='revisions')renderRevisions();else if(day())renderDaily();else $('content').innerHTML=shell('Shooting days','<p class="empty">This production has no active shooting days. Production records and issued revisions are retained. Add a day using +, or restore a deleted day.</p>');}
function bindFields(){
 bindPageLengths();bindClockTimes();bindTemperatures();document.querySelectorAll('[data-bind$=".mapsUrl"]').forEach(el=>{el.addEventListener('blur',()=>lookupLocationCoordinates(project.locations[Number(el.dataset.bind.split('.')[1])]?.id));el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();el.blur();}});});
 document.querySelectorAll('[data-bind]').forEach(el=>{if(el.dataset.clockTime||el.dataset.temperature)return;el.addEventListener('input',()=>{
  if(!el.checkValidity()){el.reportValidity();return;}
  const path=el.dataset.bind;let value=/^days\.\d+\.mealOffset$/.test(el.dataset.bind)?Number(el.value):el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''&&/(?:latitude|longitude|parkingLatitude|parkingLongitude|basecampLatitude|basecampLongitude|hospitalLatitude|hospitalLongitude)$/.test(path)?null:Number(el.value)):el.value;
  if(/^days\.\d+\.date$/.test(path)){if(!Days.validDate(value))return;const inverse=Days.apply(project,{kind:'date',id:day().id,date:value});undoDays.push(inverse);redoDays=[];revealDay();mark();renderHeader();renderSide();return;}
  put(path,value);if(/^locations\.\d+\.(latitude|longitude)$/.test(path)){const location=project.locations[Number(path.split('.')[1])];location.coordinateSource={kind:'manual'};coordinateLookupState.delete(project.id+':'+location.id);refreshLocationMapInfo('locations.'+path.split('.')[1]+'.mapsUrl');}if(path==='timeDisplayClock')writePreference('default-time-display',value);if(path==='temperatureUnit')writePreference('default-temperature-unit',value);refreshLocationMapInfo(path);if(/^days\.\d+\.schedule\.\d+\.notes$/.test(path)){const item=day().schedule[Number(path.split('.')[3])],note=el.closest('label').querySelector('small');if(note)note.innerHTML='This schedule row only. <button type="button" data-scene-notes-reset="'+esc(item.id)+'">Use production scene notes</button>';}if(/^scenes\.\d+\.(number|slug)$/.test(path)){const sc=project.scenes[Number(path.split('.')[1])],title=document.querySelector(`[data-scene-card="${sc.id}"]>summary span`);if(title)title.textContent=sc.number+' · '+(sc.slug||'Untitled scene');}if(/^locations\.\d+\.name$/.test(path)){const loc=project.locations[Number(path.split('.')[1])];const title=document.querySelector(`[data-location-card="${loc.id}"]>summary span`);if(title)title.textContent=value||'New location';}if(path.includes('.sheetOverrides.')){const note=el.closest('label').querySelector('small');if(note)note.innerHTML=`Day override <button data-sheet-reset="${path.split('.').at(-1)}" type="button">Reset to production</button>`;}
  if(/(\.date|\.zone|latitude|longitude|primaryLocationId)$/.test(path)){for(const d of project.days)d.weather.approved=false;}
  if(/weather\.summary$/.test(path)&&day().weather.mode==='nws'){day().weather.mode='manual';delete day().weather.key;delete day().weather.fetchedAt;day().weather.approved=false;}
  mark();renderHeader();if(/layout\.preset$/.test(path))renderDaily();
 });});
}
function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>refreshPreview().catch(error),550);}
function fitPreview(frame){const fit=()=>{if(!frame?.isConnected)return;const doc=frame.contentDocument;if(!doc?.body)return;const width=day().layout.paper==='Letter'?816:794;doc.documentElement.style.zoom=String(Math.min(1,Math.max(.2,frame.clientWidth/width)));frame.style.height=Math.ceil(doc.body.getBoundingClientRect().height+25)+'px';};frame.onload=()=>frame.contentDocument.fonts.ready.then(fit);previewObserver?.disconnect();previewObserver=new ResizeObserver(fit);previewObserver.observe(frame.parentElement);}
async function refreshPreview(){if(!$('preview')||!day())return;const serial=++previewSerial;try{await flush();const result=await api.request('preview',{projectId:project.id,dayId});if(serial!==previewSerial||!$('preview'))return;if(locked()){lockedDisplay[project.id+':'+day().lockedRevisionId]=result.display;renderHeader();}const frame=$('preview');fitPreview(frame);frame.srcdoc=result.html;refreshSolarSummary(result.solar);$('preview-note').textContent=locked()?'Preserved issued values / original PDF retained':`Draft preview / ${day().layout.paper} / ${result.review.errors.length} required fixes / ${result.review.warnings.length} review notes`;}catch(e){if(serial===previewSerial&&$('preview-note'))$('preview-note').textContent='Preview not updated: '+e.message;}}
function modal(title,body,actions=[]){$('modal-body').onclick=null;$('modal-body').onchange=null;$('modal-body').onkeydown=null;$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal-error').textContent='';$('modal-actions').innerHTML='<button data-modal-cancel>Cancel</button>'+actions.map((a,i)=>`<button data-modal-action="${i}" class="${a.primary?'primary':''} ${a.danger?'danger':''}">${esc(a.label)}</button>`).join('');modalAction=actions;if(!$('modal').open)$('modal').showModal();}
function closeModal(){if(!productionBusy)$('modal').close();}
$('modal').addEventListener('cancel',e=>{if(productionBusy)e.preventDefault();});
function addCall(personId){if(Records.deleted(project,'people',personId))return;if(day().calls.some(c=>c.personId===personId))return;day().calls.push({id:uid(),personId,...CallDefaults.initial(project,day(),project.people.find(p=>p.id===personId)),offset:0,pickup:'',makeup:'',ready:'',notes:''});}
function addDayData(date,label){return {id:uid(),label,date,unit:day()?.unit||'A',lunchMode:'auto',overrides:{},sheetOverrides:{},background:[],schedule:[],calls:[],weather:{mode:'manual',summary:'',approved:false},layout:clone(day()?.layout||{preset:'gcasper',sceneColors:true,paper:'A4',clock:'24',temperature:'C',mono:false,includeContacts:false,order:Object.keys(sectionLabel),hidden:[],custom:[]}),baseRevisionId:null};}
function dayDialog(duplicate=false){const initialDate=duplicate?(day()?.date||new Date().toISOString().slice(0,10)):Days.nextDayDate(project.days);modal(duplicate?'Duplicate shooting day':'Add shooting day',`<div class="form-grid"><label class="field">Day label<input id="new-day-label" value="Day ${String(project.days.length+1).padStart(2,'0')}"></label><label class="field">Date<input type="date" id="new-day-date" value="${esc(initialDate)}"></label></div><p>${duplicate?'A separate draft will copy calls, schedule and layout. Weather approval and issued state reset.':'Days have stable identities independent of their dates. Multiple units can share one date.'}</p>`,[{label:duplicate?'Create copy':'Add day',primary:true,run:async()=>{const date=$('new-day-date').value;if(!date)throw Error('Choose a shooting date.');let d=duplicate?clone(day()):addDayData(date,$('new-day-label').value);d.id=uid();d.label=$('new-day-label').value||'New day';d.date=date;d.lockedRevisionId=null;d.baseRevisionId=null;d.weather={mode:'manual',summary:'',approved:false};d.calls.forEach(c=>c.id=uid());d.schedule.forEach(c=>c.id=uid());project.days.push(d);dayId=d.id;revealDay();mark();await flush();closeModal();render();}}]);}
function weekLabel(g){return g.key==='undated'?'Dates needed':`${g.key} – ${g.end}`;}
function chooseWeek(key){const g=Days.weeks(project.days).find(g=>g.key===key);if(!g)return;visibleWeek=key;weekPage=0;dayId=g.days[0].id;render();}
function daysOverview(){const groups=Days.weeks(project.days);modal('All shooting days',`<p>Calendar weeks run Monday–Sunday. Gaps are retained; weeks without shooting days are skipped. Equal dates keep production order. Sidebar shows up to seven records at a time.</p><div class="weeks-overview">${groups.map((g,i)=>`<section class="shoot-week ${g.key===visibleWeek?'selected-week':''}"><header><h3>Week ${i+1} · ${esc(weekLabel(g))}</h3><button data-choose-week="${g.key}">Choose week ${i+1}</button></header><div class="week-strip">${g.days.map(d=>`<button class="overview-day ${d.id===dayId?'selected-day':''}" data-day="${d.id}" aria-current="${d.id===dayId?'date':'false'}"><strong>${esc(d.label)}</strong><span>${esc(d.date||'Date needed')}</span><small>Unit ${esc(d.unit||'—')} · ${d.schedule.length} schedule items${d.lockedRevisionId?' · Issued':''}</small></button>`).join('')}</div></section>`).join('')||'<p class="empty">No shooting days. Add a day with + or restore a deleted day.</p>'}</div>`,[]);}
async function changeDay(command,stack=undoDays){
 const before=clone(project),oldSelected=dayId;const oldOrder=Days.ordered(project.days),index=oldOrder.findIndex(d=>d.id===dayId);
 const inverse=Days.apply(project,command);if(!project.days.some(d=>d.id===dayId))dayId=Days.ordered(project.days)[Math.min(Math.max(index,0),project.days.length-1)]?.id;
 mark();try{await flush();}catch(e){project=before;dayId=oldSelected;mark();render();throw e;}
 stack.push(inverse);revealDay();render();return inverse;
}
function dayActions(id){const d=project.days.find(d=>d.id===id);if(!d)return;modal('Shooting day actions',`<p><b>${esc(d.label)}</b> · ${esc(d.date||'Date needed')} · Unit ${esc(d.unit)}</p>`,[{label:'Change Date',run:async()=>dateDialog(id)},{label:'Delete',run:async()=>deleteDay(id)}]);}
function dateDialog(id){const d=project.days.find(d=>d.id===id);if(!d)return;modal('Change shooting date',`<p>${esc(d.label)} keeps its identity, calls, schedule and layout. The sidebar and overview sort by date; equal dates keep production order. Issued PDFs retain their original date and bytes. This day's weather approval resets.</p><label class="field">New shooting date<input id="change-day-date" type="date" min="1900-01-01" max="2100-12-31" value="${esc(d.date)}"></label>`,[{label:'Change Date',primary:true,run:async()=>{await changeDay({kind:'date',id,date:$('change-day-date').value});redoDays=[];closeModal();renderSide();}}]);}
async function deleteDay(id){const d=project.days.find(d=>d.id===id);if(!d)return;const remove=async suppress=>{await changeDay({kind:'delete',id});redoDays=[];if(suppress)writePreference('confirm-day-deletion',false);closeModal();renderSide();toast('Day moved to Deleted days. Restore it there or use Undo day change.');};if(readPreference('confirm-day-deletion',true)===false)return remove(false);
 modal('Delete shooting day?',`<p>Move <b>${esc(d.label)}</b> (${esc(d.date||'Date needed')}, Unit ${esc(d.unit)}) to Deleted days?</p><p>Only this day leaves the active schedule. Its calls, schedule, layout and IDs are retained for restoration, including after reopening. Production cast, crew, scenes, locations, other shooting days and all original issued PDFs remain. Restore from Deleted days or use Undo day change.</p><label class="check"><input id="suppress-day-warning" type="checkbox"> Don't show again</label><p class="tiny">Settings → Reset Warnings restores this confirmation.</p>`,[{label:'Delete shooting day',primary:true,run:async()=>remove($('suppress-day-warning').checked)}]);
}
function showDeletedDays(){modal('Deleted shooting days',`<p>Days are retained in this project and its exported archive. Restoring retains the original day ID, contents and issued links.</p>${(project.deletedDays||[]).map(d=>`<article class="deleted-day"><div><strong>${esc(d.label)}</strong><p>${esc(d.date||'Date needed')} · Unit ${esc(d.unit)} · ${d.schedule.length} schedule items · ${d.calls.length} calls</p></div><button data-restore-day="${d.id}">Restore ${esc(d.label)}</button></article>`).join('')||'<p class="empty">No deleted shooting days.</p>'}`,[]);}
$('days-overview').onclick=()=>transition(async()=>daysOverview());$('deleted-days').onclick=()=>transition(async()=>showDeletedDays());
$('undo-day').onclick=()=>transition(async()=>{const command=undoDays.at(-1);if(command){await changeDay(command,redoDays);undoDays.pop();renderSide();}});
$('redo-day').onclick=()=>transition(async()=>{const command=redoDays.at(-1);if(command){await changeDay(command,undoDays);redoDays.pop();renderSide();}});
$('days').addEventListener('contextmenu',e=>{const row=e.target.closest('[data-day],[data-day-options]');if(row){e.preventDefault();transition(async()=>dayActions(row.dataset.day||row.dataset.dayOptions));}});
$('days').addEventListener('keydown',e=>{if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10'){const row=e.target.closest('[data-day],[data-day-options]');if(row){e.preventDefault();transition(async()=>dayActions(row.dataset.day||row.dataset.dayOptions));}}});

async function issue(){
 await flush();if(locked()){day().lockedRevisionId=null;mark();await flush();render();toast('New draft created. Earlier issued PDFs remain unchanged.');return;}
 const check=await api.request('review',{projectId:project.id,dayId});
 modal('Review before issue',`<p>Issue a frozen snapshot and preserve its original PDF. Future edits start a new draft.</p>${check.errors.length?'<h3>Required fixes</h3><ul class="issues errors">'+check.errors.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p>No blocking errors.</p>'}${check.warnings.length?'<h3>Review notes</h3><ul class="issues">'+check.warnings.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><label class="check"><input type="checkbox" id="ack-warnings"> I reviewed these warnings and approve this revision.</label>':''}`,check.errors.length?[]:[{label:'Issue revision',primary:true,run:async()=>{const ack=!check.warnings.length||$('ack-warnings')?.checked;if(!ack)throw Error('Acknowledge the review notes before issuing.');const state=await api.request('issue',{projectId:project.id,dayId,version,acknowledgeWarnings:ack});closeModal();await useState(state);toast('Revision issued and original PDF preserved locally.');}}]);
}
async function forecastDialog(){await flush();const loc=primaryLocation();modal('Online weather request',`<p>NWS will receive the selected latitude/longitude, your IP address and an app identifier. It covers supported US locations for about seven days. Your project title, cast and crew are not sent.</p><div class="inline-notice">${esc(loc?.name||'No location')}<br>${esc(loc?.latitude??'Missing latitude')}, ${esc(loc?.longitude??'Missing longitude')}<br>${esc(day().date)} / ${esc(effectiveZone())}</div><label class="check"><input id="forecast-consent" type="checkbox"> Allow this single forecast request to NWS.</label><p>Manual weather and offline solar work without permission.</p>`,[{label:'Retrieve forecast',primary:true,run:async()=>{if(!$('forecast-consent').checked)throw Error('Select permission to send this location to NWS.');const state=await api.request('forecast',{projectId:project.id,dayId,consent:true});closeModal();await useState(state);section='weather';render();toast('Forecast cached. Review and approve it before issue.');}}]);}
async function pdfExport(revisionId){await flush();const result=await api.request('exportPDF',{projectId:project.id,dayId,revisionId});if(!result.canceled)toast('PDF saved: '+result.path);}
const actions={
 'availability-cast':()=>transition(async()=>showAvailability('cast')),'availability-crew':()=>transition(async()=>showAvailability('crew')),
 'company-image':chooseCompanyImage,'company-image-remove':()=>setCompanyImage({mode:'none'}),'company-image-default':()=>setCompanyImage({mode:'default'}),
 'lunch-auto':()=>transition(async()=>{if(locked())return;Lunch.automatic(day());mark();await flush();renderDaily();}),
 'solar-edit':()=>transition(async()=>solarDialog()),'solar-reset':()=>{if(locked())return;delete day().solarOverrides;mark();refreshPreview();},
 'source-details':()=>{const p=project.productionDesk;if(!p)return;modal('Production Desk source details',`<p>Source ID: ${esc(p.sourceId)}<br>Scenario: ${esc(p.scenarioId)}<br>File SHA-256: ${esc(p.hash)}</p><p>All source categories, breakdowns, script, shots, calendars, scenarios, availability and annotation metadata are retained below. PDF bytes stay in the original .productiondesk file. This view is read-only.</p><pre>${esc(JSON.stringify(p.model,null,2))}</pre>`,[]);},
 'edit-locations':()=>{view='production';master='locations';render();},
 'new-draft':issue,'pdf':()=>pdfExport(),'refresh-preview':refreshPreview,
 'forecast':forecastDialog,
 'manual-weather':()=>{day().weather={mode:'manual',summary:day().weather.summary,approved:false};mark();render();},
 'add-scene':()=>{const id=$('add-scene-select').value,s=project.scenes.find(s=>s.id===id);if(!s||Records.deleted(project,'scenes',s.id))return toast('Choose an active scene to add.');day().schedule.push({id:uid(),type:'scene',sceneId:id,description:'',start:'',offset:0,duration:s.durationMinutes||60});s.castIds.forEach(addCall);mark();render();},
 'add-break':()=>{day().schedule.push({id:uid(),type:'meal',sceneId:'',description:'Meal break',start:'12:30',offset:0,duration:30});mark();render();},
 'custom-section':()=>{day().layout.custom.push({title:'Additional information',text:''});mark();render();},
 'add-background':()=>{day().background.push({id:uid(),type:'background',quantity:1,description:'',call:'',notes:''});mark();render();},
 'add-cast':()=>addPerson('cast'),'add-crew':()=>addPerson('crew'),
 'add-location':()=>{const locationId=uid();const expanded=readPreference('location-cards:'+project.id,{});expanded[locationId]=true;writePreference('location-cards:'+project.id,expanded);project.locations.push({id:locationId,name:'New location',address:'',latitude:null,longitude:null,zone:project.defaults.zone,parking:'',hospital:'',emergencyPhone:'',verified:false});mark();render();},
 'add-scene-master':()=>{const sceneId=uid(),pref=readPreference('scene-cards:'+project.id,{});pref[sceneId]=true;writePreference('scene-cards:'+project.id,pref);project.scenes.push({id:sceneId,number:String(project.scenes.length+1),slug:'INT. NEW SET - DAY',synopsis:'',eighths:0,castIds:[],locationId:'',script:'',shots:[],durationMinutes:60});mark();render();}
};
function addPerson(type){project.people.push({id:uid(),name:'New '+(type==='cast'?'performer':'crew member'),type,role:'',department:type==='cast'?'Cast':'Production',character:'',email:'',phone:''});mark();render();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 try{
  if(b.hasAttribute('data-modal-cancel'))return closeModal();
  if(b.dataset.modalAction!==undefined){b.disabled=true;try{await modalAction[Number(b.dataset.modalAction)].run();}catch(err){$('modal-error').textContent=err.message;}finally{b.disabled=false;}return;}
  if(b.dataset.coordinateLookup)return lookupLocationCoordinates(b.dataset.coordinateLookup);
  if(b.dataset.coordinateUse){const loc=project.locations.find(l=>l.id===b.dataset.coordinateUse),state=coordinateLookupState.get(project.id+':'+loc?.id);if(!loc||!state?.result||state.result.inputURL!==loc.mapsUrl)throw Error('Resolve the current link first.');return applyMapCoordinates(loc,state.result,window.LocationMaps.capture(loc),true);}
  if(b.dataset.sceneNotesReset){const row=day()?.schedule.find(s=>s.id===b.dataset.sceneNotesReset);if(locked()||!row||row.type!=='scene')throw Error('Choose an editable scene row.');delete row.notes;mark();return renderDaily();}
  if(b.dataset.recordDelete){const [entity,id]=b.dataset.recordDelete.split(':');return transition(async()=>deleteRecordDialog(entity,id));}
  if(b.dataset.recordTrash){const [entity,type]=b.dataset.recordTrash.split(':');return transition(async()=>showDeletedRecords(entity,type));}
  if(b.dataset.sceneCollapse||b.dataset.sceneExpand){commitPageLengths();const open=!!b.dataset.sceneExpand,pref=readPreference('scene-cards:'+project.id,{});for(const scene of activeScenes())pref[scene.id]=open;writePreference('scene-cards:'+project.id,pref);document.querySelectorAll('[data-scene-card]').forEach(el=>el.open=open);return;}
  if(b.dataset.locationCollapse||b.dataset.locationExpand){const open=!!b.dataset.locationExpand,pref=readPreference('location-cards:'+project.id,{});for(const loc of activeLocations())pref[loc.id]=open;writePreference('location-cards:'+project.id,pref);document.querySelectorAll('[data-location-card]').forEach(el=>el.open=open);return;}
  if(b.dataset.callCollapse||b.dataset.callExpand){const position=captureCallView(callScope(section));for(const card of document.querySelectorAll('[data-call-card]'))if(!card.hidden)card.open=!!b.dataset.callExpand;restoreCallView(position);return;}
  if(b.dataset.mapUse||b.dataset.mapOpen){const [id,kind]=(b.dataset.mapUse||b.dataset.mapOpen).split(':');const index=project.locations.findIndex(l=>l.id===id);if(index<0||Records.deleted(project,'locations',id)||!Object.hasOwn(Details.places,kind))throw Error('Location no longer exists.');const loc=project.locations[index],spec=Details.places[kind];if(b.dataset.mapOpen){await flush();return await api.request('openLocationMap',{projectId:project.id,locationId:id,kind});}const info=window.LocationMaps.inspect(loc[spec.link]);if(!info.text)throw Error('No usable address text in this link.');const path=`locations.${index}.`+spec.address;put(path,info.text);const input=document.querySelector(`[data-bind="${path}"]`);if(input){input.value=info.text;input.focus();}mark();refreshLocationMapInfo(path);return;}
  if(b.dataset.dayOptions)return transition(async()=>dayActions(b.dataset.dayOptions));
  if(b.dataset.weekStep)return transition(async()=>{const groups=Days.weeks(project.days);const i=groups.findIndex(g=>g.key===visibleWeek);const g=groups[i+Number(b.dataset.weekStep)];if(g)chooseWeek(g.key);});
  if(b.dataset.weekPage){weekPage+=Number(b.dataset.weekPage);return renderSide();}
  if(b.hasAttribute('data-reveal-day')){revealDay();return renderSide();}
  if(b.dataset.chooseWeek)return transition(async()=>{chooseWeek(b.dataset.chooseWeek);closeModal();});
  if(b.dataset.restoreDay)return transition(async()=>{await changeDay({kind:'restore',id:b.dataset.restoreDay});redoDays=[];selectDay(b.dataset.restoreDay);showDeletedDays();});
  if(b.dataset.day)return transition(async()=>{selectDay(b.dataset.day);if($('modal').open)closeModal();});
  if(b.dataset.view)return transition(async()=>{view=b.dataset.view;render();});
  if(b.dataset.section)return transition(async()=>{view='daily';section=b.dataset.section;render();});
  if(b.dataset.master){master=b.dataset.master;await flush();return renderProduction();}
  if(b.dataset.template){day().layout.preset=b.dataset.template;mark();return render();}
  if(b.dataset.sheetReset){delete day().sheetOverrides[b.dataset.sheetReset];mark();return render();}
  if(b.dataset.reset){delete day().overrides[b.dataset.reset];mark();return render();}
  if(b.dataset.action){await actions[b.dataset.action]?.();return;}
  if(b.dataset.move){const [kind,a,delta]=b.dataset.move.split(':'),i=Number(a),list=kind==='layout'?day().layout.order:day().schedule,j=kind==='schedule'?Records.scheduleNeighbor(project,list,i,Number(delta)):i+Number(delta);if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];mark();return render();}
  if(b.dataset.remove){const [kind,i]=b.dataset.remove.split(':');(kind==='custom'?day().layout.custom:kind==='background'?day().background:day().schedule).splice(Number(i),1);mark();return render();}
  if(b.dataset.script){const s=project.scenes.find(s=>s.id===b.dataset.script);modal(s.number+' · '+s.slug,`<p>${esc(s.synopsis)}</p><p class="tiny">Local scene ID: ${esc(s.id)}<br>Source ID: ${esc(s.sourceId||'User-created')}</p>${s.script?'<pre>'+esc(s.script)+'</pre>':'<p>No screenplay text supplied by this source.</p>'}${s.shots?.length?'<h3>Source shots & camera setups</h3>'+s.shots.map(shot=>'<article class="row-card"><p><b>'+esc(shot.number)+' · '+esc(shot.name)+'</b><br>'+esc(shot.description||'')+'</p><p>'+esc(shot.size)+' / Camera '+esc(shot.camera||'—')+' / '+esc(shot.lens)+' mm / '+esc(shot.movement||'')+' / '+esc(shot.equipment||'')+'</p><p>'+esc(shot.day||'Unscheduled')+' · '+esc(shot.status||'')+' · takes '+esc(shot.takes??'')+' · circle '+esc(shot.circleTake||'—')+'<br>Setup '+esc(shot.setupMinutes??'—')+' min / shoot '+esc(shot.shootMinutes??'—')+' min / actual '+esc(shot.actualMinutes||'—')+' min</p><p class="tiny">Shot ID: '+esc(shot.id)+'<br>Source shot ID: '+esc(shot.sourceId||'Not supplied')+'<br>Camera object: '+esc(shot.cameraObjectId||'Not supplied')+'</p><p>'+esc(shot.notes)+'</p></article>').join(''):''}`,[]);return;}
  if(b.dataset.revisionExport)return pdfExport(b.dataset.revisionExport);
  if(b.dataset.revisionPreview){const r=await api.request('revision',{projectId:project.id,revisionId:b.dataset.revisionPreview});modal('Issued R'+r.number,`<p>Issued ${esc(r.issued)}. SHA-256 ${esc(r.hash)}</p><iframe id="revision-frame" sandbox="allow-same-origin" title="Issued revision preview" width="100%" height="500"></iframe>`,[]);$('revision-frame').srcdoc=r.html;}
 }catch(err){error(err);}
});
document.addEventListener('change',e=>{const el=e.target;
 if(el.dataset.attend){const position=captureCallView(callScope(section),el.dataset.attend);if(el.checked)addCall(el.dataset.attend);else day().calls=day().calls.filter(c=>c.personId!==el.dataset.attend);refreshCallList(position);}
 if(el.dataset.hide){const k=el.dataset.hide;day().layout.hidden=day().layout.hidden.filter(x=>x!==k);if(!el.checked)day().layout.hidden.push(k);mark();}
 if(el.dataset.sceneCast){const [i,id]=el.dataset.sceneCast.split(':');project.scenes[i].castIds=project.scenes[i].castIds.filter(x=>x!==id);if(el.checked)project.scenes[i].castIds.push(id);mark();}
});
