$('modal-close').onclick=closeModal;
function diagnosticNotice(state){
 if(boot)boot.diagnostics=state;const notice=$('diagnostic-notice');notice.hidden=!state.pending&&state.available;
 $('diagnostic-summary').textContent=state.pending?'A failure or interrupted session was recorded locally. An interruption may be a crash, force quit or power loss. Nothing has been sent.':'Local diagnostic recording is unavailable. You can still report a bug manually.';
 $('dismiss-diagnostics').hidden=!state.pending;
}
function reportBug(form={description:'',steps:'',includeDiagnostics:true}){
 modal('Report a Bug',`<p>To: <b>alexanderhosier@squidproductions.org</b></p><p>Describe what went wrong without adding private production details. App version and OS are included. Project/script/media contents, raw error messages, contacts, secrets and personal paths are excluded from automatic diagnostics. Common paths and credentials in your description are redacted; review the result before sharing.</p><label class="field">Description<textarea id="report-description" maxlength="3000" rows="4">${esc(form.description)}</textarea></label><label class="field">Steps to reproduce<textarea id="report-steps" maxlength="3000" rows="3">${esc(form.steps)}</textarea></label><label class="check"><input id="report-diagnostics" type="checkbox" ${form.includeDiagnostics?'checked':''}>Include sanitized diagnostic summary (up to 5 recent failures)</label><p class="tiny">Event log: at most 40 events / 32 KB, retained for 14 days. No memory dumps or automatic uploads. Copy/export remain available without a mail client.</p>`,[{label:'Review report',primary:true,run:async()=>{const values={description:$('report-description').value,steps:$('report-steps').value,includeDiagnostics:$('report-diagnostics').checked};const draft=await api.request('reportPreview',values);reportReview(values,draft);}}]);$('report-description').focus();
}
function reportReview(form,draft){
 modal('Review bug report',`<p>Recipient: <b>${esc(draft.to)}</b></p><label class="field">Full report to share<textarea id="report-preview" readonly rows="12">${esc(draft.text)}</textarea></label><p>Only this reviewed text will be copied, exported or handed to your default mail client. Opening a draft does not confirm delivery. No email is sent automatically.</p><p id="report-result" role="status" aria-live="polite"></p>`,[
  {label:'Edit details',run:()=>reportBug(form)},
  {label:'Copy report',run:async()=>{await api.request('reportCopy',{id:draft.id});$('report-result').textContent='Reviewed report copied. Paste it in your email client and send when ready.';}},
  {label:'Export report',run:async()=>{const r=await api.request('reportExport',{id:draft.id});$('report-result').textContent=r.canceled?'Export canceled.':'Reviewed report exported. Nothing was sent.';}},
  {label:'Open mail draft',primary:true,run:async()=>{const r=await api.request('reportMail',{id:draft.id});$('report-result').textContent=r.reason;}}
 ]);$('report-preview').focus();
}
$('report-bug').onclick=()=>reportBug();$('review-diagnostics').onclick=()=>reportBug();$('dismiss-diagnostics').onclick=async()=>{try{diagnosticNotice(await api.request('diagnosticDismiss'));}catch(e){error(e);}};
window.ScriptCallReports.onOpen(()=>reportBug());window.ScriptCallReports.onStatus(diagnosticNotice);
function settingsDialog(){modal('Settings & help',`<p><b>Script Call ${esc(boot?.version||'')}</b></p><p>Production data stays on this computer. Export project includes preserved issued PDFs; Open project imports a separate copy. Production Desk imports are reviewed before applying changes.</p><p>Data: ${esc(boot?.dataDirectory)}</p><p>Font discovery: Reross ${boot?.fontAvailable?'available':'using fallback'}. G-Casper uses bundled Montserrat and Nunito.</p><fieldset class="time-display-setting"><legend>Time display</legend><label class="check"><input type="radio" name="time-display" value="24" ${timeMode()==='24'?'checked':''}>24-hour (military)</label><label class="check"><input type="radio" name="time-display" value="12" ${timeMode()==='12'?'checked':''}>12-hour (AM/PM)</label><p class="tiny">Saved with this production and used for new productions on this device. Times and zones stay unchanged; issued PDFs keep their original format.</p></fieldset><fieldset><legend>Temperature display</legend><label class="check"><input type="radio" name="temperature-display" value="C" ${tempMode()==='C'?'checked':''}>Celsius (°C)</label><label class="check"><input type="radio" name="temperature-display" value="F" ${tempMode()==='F'?'checked':''}>Fahrenheit (°F)</label><p class="tiny">Saved with this production and used for new productions on this device. Existing days retain their previous unit until you choose here. Canonical Celsius values and issued PDFs stay unchanged.</p></fieldset>`,[{label:'Delete Production',danger:true,run:deleteProductionDialog},{label:'Deleted productions',run:showDeletedProductions},{label:'Deleted members & locations',run:()=>showDeletedRecords()},{label:'Deleted scenes',run:()=>showDeletedRecords('scenes')},{label:'Reset Warnings',run:async()=>{writePreference('confirm-day-deletion',true);toast('Shooting day deletion confirmation restored.');}},{label:'Toggle light / dark',run:async()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('callsheet-theme',dark?'dark':'light');}}]);$('modal-body').onchange=async event=>{const radio=event.target;if(!['time-display','temperature-display'].includes(radio.name)||!radio.checked)return;const controls=[...$('modal-body').querySelectorAll('[name="time-display"],[name="temperature-display"]')];controls.forEach(el=>el.disabled=true);try{commitPageLengths();const temperature=radio.name==='temperature-display';project[temperature?'temperatureUnit':'timeDisplayClock']=radio.value;mark();await flush();writePreference(temperature?'default-temperature-unit':'default-time-display',radio.value);render();toast(temperature?'Temperature display saved. Stored Celsius values are unchanged.':'Time display saved. Stored times are unchanged.');}catch(e){$('modal-error').textContent=e.message;}finally{controls.forEach(el=>el.disabled=false);}};}
async function productionChange(run){
 if(productionBusy)return;productionBusy=true;const controls=[...$('modal').querySelectorAll('button')];controls.forEach(b=>b.disabled=true);
 try{const result=await run();clearTimeout(saveTimer);clearTimeout(previewTimer);previewSerial++;productionBusy=false;closeModal();view='daily';section='overview';master='general';await useState(result.state);$('save-state').textContent='Saved on this device';return result;}finally{productionBusy=false;controls.forEach(b=>b.disabled=false);}
}
async function deleteProductionDialog(){
 await flush();const selected={id:project.id,version,title:project.title};
 modal('Delete production?',`<p>Delete <b>${esc(selected.title)}</b> from the active productions list?</p><p>This includes all of its shooting days (including deleted days), cast and crew, scenes, schedules, calls, availability, layouts, import links and issued revisions/PDFs.</p><p>The complete production is retained in <b>Settings & help → Deleted productions</b> in this app profile. Restore it there with its original IDs and PDFs, including after reopening. A local backup is made before deletion.</p><p>Other productions, app settings and external imported/exported files are unchanged. If this is the last active production, a new blank production opens.</p>`,[{label:'Delete Production',primary:true,run:async()=>{if(productionBusy)return;if(project.id!==selected.id||version!==selected.version||project.title!==selected.title)throw Error('Selected production changed. Close this dialog and review the selected production.');const result=await productionChange(async()=>{await flush();if(project.id!==selected.id||version!==selected.version)throw Error('Production changed. Close this dialog and review it before deleting.');return api.request('deleteProduction',{id:selected.id,version:selected.version});});if(result)toast('Production moved to Deleted productions. Restore it in Settings & help.');}}]);
}
async function showDeletedProductions(){
 const entries=await api.request('deletedProductions');
 modal('Deleted productions',`<p>Complete productions and their original issued PDFs stay in this local profile until restored. They are not included when exporting a different production. Restoring keeps the original production, person, scene, day and import IDs.</p>${entries.map(p=>`<article class="deleted-day"><div><strong>${esc(p.title)}</strong><p>${p.dayCount} shooting days · ${p.issuedRevisions} issued revisions<br>Deleted ${esc(new Date(p.deletedAt).toLocaleString())}</p></div><button data-restore-production="${esc(p.id)}">Restore ${esc(p.title)}</button></article>`).join('')||'<p class="empty">No deleted productions.</p>'}`);
 $('modal-body').onclick=async e=>{const button=e.target.closest('[data-restore-production]');if(!button||productionBusy)return;const selected=entries.find(p=>p.id===button.dataset.restoreProduction);if(!selected)return;try{await flush();const result=await productionChange(()=>api.request('restoreProduction',{id:selected.id,version:selected.version}));if(result)toast('Production restored with its original IDs and issued PDFs.');}catch(e){$('modal-error').textContent=e.message;}};
}
$('settings').onclick=()=>transition(async()=>settingsDialog());

async function updateDialog(check=false){
 try{const state=await api.request(check?'updateCheck':'updateStatus');boot.updates=state;const actions=[];
  if(state.enabled&&!['checking','downloading','installing'].includes(state.status))actions.push({label:'Check again',run:()=>updateDialog(true)});
  if(state.status==='available')actions.push({label:'Download update',primary:true,run:async()=>{const result=await api.request('updateDownload');await updateDialog();if(result.status==='error')toast(result.reason);}});
  if(state.status==='downloaded')actions.push({label:'Save, back up & restart',primary:true,run:async()=>{await transitionQueue;await flush();await api.request('updateInstall');}});
  if(state.enabled)actions.push({label:state.automatic?'Turn off automatic checks':'Turn on automatic checks',run:async()=>{await api.request('updatePreferences',{automatic:!state.automatic});await updateDialog();}});
  modal('Script Call updates',`<p>Installed: <b>${esc(boot.version)}</b> · ${esc(state.channel||'stable')} channel</p><p>${esc(state.status)}${state.version?' · '+esc(state.version):''}</p><p>${esc(state.reason||'')}</p>${state.notes?'<p class="pre">'+esc(state.notes)+'</p>':''}<p>Updates verify signed release metadata and download checksums. Installation saves your work and creates a local recovery backup. Automatic checks ${state.automatic?'on':'off'}; downloads and restart require your choice.</p>`,actions);
 }catch(e){error(e);}
}
$('updates').onclick=()=>updateDialog(true);
api.onCheckUpdates(()=>updateDialog(true));api.onUpdates(state=>{if(boot)boot.updates=state;$('updates').textContent=state.status==='available'?'Update available':state.status==='downloaded'?'Install update':'Check for updates';if(['available','downloaded'].includes(state.status))toast('Script Call '+state.version+(state.status==='available'?' is available.':' is ready to install.'));});
function saveFailure(e){error(e);modal('Unsaved changes remain','<p>The local save failed. Keep this window open to retry. You can save the current edits as a recovery JSON copy for repair; it does not include earlier issued PDF files.</p>',[{label:'Save recovery copy',primary:true,run:async()=>{const r=await api.request('recovery',{project});if(!r.canceled)toast('Recovery data saved: '+r.path);}}]);}
api.onSave(()=>Promise.resolve().then(()=>{commitPageLengths();return flush();}).catch(error));api.onBeforeClose(async()=>{try{commitPageLengths();}catch(e){error(e);return;}try{await flush();api.closeReady();}catch(e){saveFailure(e);}});
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();Promise.resolve().then(()=>{commitPageLengths();return flush();}).catch(error);}});
initAvailabilityUI();
(async()=>{try{document.documentElement.dataset.theme=localStorage.getItem('callsheet-theme')||'light';boot=await api.request('bootstrap');$('app-version').textContent='VERSION '+boot.version;diagnosticNotice(boot.diagnostics);projects=boot.projects;await useState(await api.request('get',{id:projects[0].id}));$('save-state').textContent='Saved on this device';await api.request('portableReady');}catch(e){$('save-state').textContent='Could not open local data';error(e);}})();
